-- Owner-approved menu choices; no offers. No historical order data changes.
begin;
create temporary table tcb_menu_bases on commit drop as select * from public.products where order_type='normal';
do $$ begin if exists(select 1 from unnest(array['CMB1-1','CMB2-1','CMB3-1','CMB4-1','CMB5-1','CMB6-1','NN-1','NN-10','NN-11','NN-2','NN-3','NN-4','NN-5','NN-6','NN-7','NN-8','NN-9','NR-1','NR-10','NR-11','NR-2','NR-3','NR-4','NR-5','NR-6','NR-7','NR-8','NR-9','NS-1','NS-2','NS-3','NS-4','NS-5','NS-6','NS-7','NS-8','NSP-1','NSP-2','NSP-3','NSP-4','VN-1','VN-10','VN-2','VN-3','VN-4','VN-6','VN-7','VN-8','VN-9','VR-1','VR-10','VR-11','VR-2','VR-3','VR-4','VR-5','VR-6','VR-7','VR-9','VS-1','VS-10','VS-2','VS-3','VS-4','VS-5','VS-6','VS-7','VS-8','VS-9','VSP-1','VSP-2','VSP-3','VSP-4','VSP-5','VSP-6']::text[]) b(id) where not exists(select 1 from tcb_menu_bases p where p.id=b.id)) then raise exception 'Menu base product missing; reconcile the website catalogue before applying this migration.'; end if; end $$;
update public.products set active=false where order_type='normal' and id in ('CMB1-1','CMB1-2','CMB1-3','CMB1-4','CMB1-5','CMB1-6','CMB2-1','CMB2-2','CMB2-3','CMB2-4','CMB3-1','CMB3-2','CMB3-3','CMB3-4','CMB4-1','CMB4-2','CMB4-3','CMB4-4','CMB4-5','CMB5-1','CMB5-2','CMB5-3','CMB5-4','CMB6-1','CMB6-2','CMB6-3','CMB6-4','NS-1','NS-5','NS-6','NS-7','NS-8','VN-5','VR-8','VS-1','VS-3','VS-4','VS-5','VS-6');

commit;
